# 8. జీవని (te8) – Telugu_01T.pdf పేజీలు 33–36
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from qbh import Bank, AR, PY, PV, NN, SD, SM, VY
B = Bank(8, 'te8'); q, m = B.q, B.mcq
PG = 'కింది పరిచిత గద్యం చదివి, ఇచ్చిన ప్రశ్నలకు జవాబులు రాయండి.\n'
q(1, 8, PG + 'విశ్వనాథంగారు గొప్ప మనస్తత్వ శాస్త్రవేత్త. జీవని వ్యక్తిత్వ వికాసానికి ఆయన చేస్తున్న ప్రయోగాలు, పాప పెంపకానికిచ్చే సూచనలు ఫలితంగా జీవనిలో మార్పులు రాసాగాయి. ఆ మార్పులు నాలో గొప్ప అనుభూతిని కల్గించాయి. సత్తువలేని జీవకణాల్లో కొద్దికొద్దిగా ఊపిరి రగిలి, నెమ్మదిగా నాలుగేళ్ళకు అడుగులు వేయడం నేర్చుకుంది జీవని. అదొక మహాపోరాటం. వెదురుబొంగు వేణువుగా కావడానికి పడిన శ్రమ. లేశమైనా వెలుగు సోకని అంధకారంలో పడుతూ లేస్తూ చేస్తున్న ప్రయాణం.\nఅ) జీవని వ్యక్తిత్వ వికాసానికి ప్రయోగాలు చేస్తున్నదెవరు?\nఆ) “ఆ మార్పులు నాలో గొప్ప అనుభూతిని కల్గించాయి” అని అన్నదెవరు?\nఇ) జీవని ఎన్నేళ్ళకు అడుగులు వేయడం నేర్చుకుంది?\nఈ) పై గద్యం ఆధారంగా ఒక అర్థవంతమైన ప్రశ్నను తయారు చేయండి.',
  'అ) మనస్తత్వ శాస్త్రవేత్త విశ్వనాథంగారు.\nఆ) జీవని తల్లి లలిత.\nఇ) నాలుగేళ్ళకు.\nఈ) జీవని నడక నేర్చుకోవడాన్ని రచయిత దేనితో పోల్చారు?')
q(1, 8, PG + 'ఆ రోజు ఆదివారం. ఆ వేళ ఆకాశం కూడా హాలిడే మూడ్‌లో వుంది. తూర్పున సూర్యనేత్రం ఇంకా తెరుచుకోలేదు. జీవని ఇంకా నిద్ర లేవలేదు. ఎదురు చూడని అతిథిలా కాలింగ్ బెల్ మోగింది. తలుపు తీస్తే, జీవని స్కూల్ ప్రధానోపాధ్యాయురాలు, క్లాస్ టీచర్ మాలినీ రావు, ఆర్ట్ టీచర్ మణిభూషణ్ మొదలైనవారు ఆహ్లాదకరమైన చిరునవ్వులతో ప్రత్యక్షమయ్యారు. ఆశ్చర్యం! ఓ వైపు ఉద్వేగం ఆ క్షణం. “శుభాకాంక్షలు లలిత గారూ! జీవని పెయింటింగ్‌కి అంతర్జాతీయ గుర్తింపు వచ్చింది. ‘అమ్మ’ అనే తన పెయింటింగ్‌కి సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు వచ్చింది.”\nఅ) చిరునవ్వులతో ప్రత్యక్షమైంది ఎవరు?\nఆ) జీవని పెయింటింగ్‌కి ఎలాంటి గుర్తింపు వచ్చింది?\nఇ) జీవని పెయింటింగ్‌కి ఏ అవార్డు వచ్చింది?\nఈ) పై గద్యం ఆధారంగా ఒక అర్థవంతమైన ప్రశ్నను తయారు చేయండి.',
  'అ) జీవని స్కూల్ ప్రధానోపాధ్యాయురాలు, క్లాస్ టీచర్ మాలినీ రావు, ఆర్ట్ టీచర్ మణిభూషణ్ మొదలైనవారు.\nఆ) అంతర్జాతీయ గుర్తింపు వచ్చింది.\nఇ) “అమ్మ” పెయింటింగ్‌కి సోవియట్ లాండ్ చిల్డ్రన్స్ పెయింటింగ్స్ అవార్డు వచ్చింది.\nఈ) జీవని గీసిన పెయింటింగ్ పేరు ఏమిటి?')
q(1, 8, 'జీవనిని ఉన్నతంగా తీర్చిదిద్దడంలో తల్లి లలిత పాత్రను వివరించండి.',
  '1) ధైర్యమైన నిర్ణయం: ముప్పై ఏళ్ళ నిరీక్షణ తర్వాత కలిగిన గర్భంలో బిడ్డకు మెదడు పెరగకపోవచ్చని డాక్టర్లు చెప్పినా బిడ్డను కనాలని నిర్ణయించుకుంది.\n2) ఒంటరి పోరాటం: ప్రత్యేక అవసరాలతో పుట్టిన పాపను భర్త, అత్త, ఆడబిడ్డ పట్టించుకోకపోయినా, ఆశ్రమంలో చేర్చుదామన్నా ఒప్పుకోకుండా తానే పెంచింది.\n3) స్ఫూర్తి: వీధిలో గారడీ చేసే ఐదేళ్ళ జీవమ్మను చూసి శిక్షణ, పట్టుదలతో ఏదైనా సాధ్యమని నమ్మి పాపకు ‘జీవని’ అని పేరు పెట్టింది.\n4) నిపుణుల సహాయం: మనస్తత్వ శాస్త్రవేత్త విశ్వనాథం సూచనలు ఓపికగా పాటించి జీవని నాలుగేళ్ళకు నడక నేర్చుకునేలా చేసింది.\n5) ప్రతిభను గుర్తించడం: బడిలో అక్షరాలు రాకపోయినా జీవని ఆకాశం, మబ్బులు, పక్షుల బొమ్మలు గీయడాన్ని గమనించి, ఆ ప్రత్యేకతను గుర్తించమని ఉపాధ్యాయులను అర్థించింది; ఆర్ట్ టీచర్ మణిభూషణ్ శిక్షణ ఇప్పించింది.\n6) ఫలితం: జీవని ‘అమ్మ’ చిత్రానికి సోవియట్ లాండ్ అంతర్జాతీయ అవార్డు వచ్చింది. టీవీ ఇంటర్వ్యూలో ప్రతి ప్రశ్నకూ జీవని “అమ్మ” అని జవాబివ్వడం తల్లి ప్రేమకు నిదర్శనం.\nముగింపు: లలిత ఓపిక, ప్రేమ, ఆత్మస్థైర్యమే జీవనిని ఉన్నత స్థాయికి చేర్చాయి.')
q(1, 8, 'జీవని పాఠంలోని సన్నివేశాల ఆధారంగా లలిత, విశ్వనాథం మధ్య చర్చను సంభాషణ రూపంలో రాయండి.',
  'విశ్వనాథం: నమస్కారమమ్మా! బస్సులో మీ పాపను చూశాను. ఆమెకు ప్రత్యేక అవసరాలున్నట్లున్నాయి కదా?\nలలిత: అవునండీ. డాక్టర్లు మెదడు సరిగా పెరగలేదన్నారు. ఇంట్లోవాళ్ళు ఆశ్రమంలో చేర్చమంటున్నారు; నాకు ఇష్టం లేదు.\nవిశ్వనాథం: మీ నిర్ణయం సరైనదే అమ్మా. నేను మనస్తత్వ శాస్త్రవేత్తను. నా కూతురు ప్రమోదిని కూడా ఇలాగే పుట్టింది; ఓపికతో పెంచాను.\nలలిత: నిజమా! అయితే నా జీవనిని కూడా మామూలు పిల్లలా తయారుచేయగలనా?\nవిశ్వనాథం: తప్పకుండా. ప్రేమ, ఓపిక, క్రమమైన శిక్షణ ఇస్తే ఈ పిల్లలు అద్భుతాలు చేస్తారు. రోజూ కొన్ని వ్యాయామాలు, ఆటలు చేయించాలి; ఆమె చేసే చిన్న పనిని కూడా మెచ్చుకోవాలి.\nలలిత: మీరు చెప్పినట్లే చేస్తాను. వీధిలో గారడీ చేసే జీవమ్మను చూసే నా పాపకు ‘జీవని’ అని పేరు పెట్టాను.\nవిశ్వనాథం: చక్కని పేరు! ఆమెకు ఏ విషయంలో ఆసక్తి ఉందో గమనించండి – ఆ దిశగా ప్రోత్సహించండి.\nలలిత: ఆమె ఆకాశం, మబ్బులు, పక్షుల బొమ్మలు గీస్తుందండి.\nవిశ్వనాథం: అదే ఆమె బలం! మంచి ఆర్ట్ టీచర్ దగ్గర శిక్షణ ఇప్పించండి. ఒకరోజు ఆమె మిమ్మల్ని గర్వపడేలా చేస్తుంది.\nలలిత: మీ మాటలు నాకు కొత్త శక్తినిచ్చాయి. కృతజ్ఞతలండీ!')
q(1, 4, 'కథ / కథానిక ప్రక్రియను వివరించండి.',
  '• కథ (కథానిక) ఆధునిక వచన ప్రక్రియ; ఆంగ్లంలో ‘Short Story’.\n• జీవితంలోని ఒక ముఖ్యమైన సన్నివేశాన్ని కళాత్మకంగా, క్లుప్తంగా చిత్రిస్తుంది.\n• పాత్రలు, నేపథ్యం, కథనం, సంభాషణలు, వాస్తవిక చిత్రణ, ఏకాగ్రత, ఆసక్తికరమైన ముగింపు దీని ముఖ్య లక్షణాలు.\n• పాఠకుని మనసులో ఒక సందేశం / అనుభూతిని గాఢంగా నిలుపుతుంది.\n• “జీవని” డా. వి. చంద్రశేఖరరావు రాసిన కథ; ఇది నాటకంగా 1991లో ఆకాశవాణి జాతీయ ఉత్తమ నాటక బహుమతి పొందింది.')
m(1, 'వెన్నెలరాకతో అంధకారం తొలిగిపోయింది. (గీత గీసిన పదం: అంధకారం) సరైన అర్థం గుర్తించండి.', ['వెలుగు', 'చీకటి', 'వెన్నెల', 'కాంతి'], 1, mk=2)
m(1, 'కష్టకాలంలోనే ఆత్మస్థైర్యం కలిగి ఉండాలి. (గీత గీసిన పదం: ఆత్మస్థైర్యం) సరైన అర్థం గుర్తించండి.', ['ధైర్యం', 'భయం', 'గౌరవం', 'అభయం'], 0, mk=2)
for w, a in [('వేణువు', 'మురళి, పిల్లనగ్రోవి'), ('లేశము', 'కొంచెం'), ('విన్యాసాలు', 'ప్రదర్శనలు, విధానాలు')]:
    q(1, 2, f'‘{w}’ {AR}', a)
m(1, 'సూర్యుడు పగటికి రాజు. (గీత గీసిన పదం: సూర్యుడు) సరైన పర్యాయపదాలు గుర్తించండి.', ['రవి, భానుడు', 'తక్రము, మజ్జిగ', 'నీళ్ళు, సలిలము', 'నెయ్యి, ఘృతము'], 0, mk=2)
m(1, 'శిక్షణ లేకుండా ఏ విద్య పూర్తికాదు. (గీత గీసిన పదం: శిక్షణ) సరైన పర్యాయపదాలు గుర్తించండి.', ['తర్ఫీదు, అభ్యాసం', 'తర్ఫీదు, బాధ్యత', 'శిక్షణ, ప్రయత్నం', 'అభ్యాసం, బాధ్యత'], 0, mk=2)
for w, a in [('కోరిక', 'కాంక్ష, ఆకాంక్ష, వాంఛ, ఇచ్ఛ'), ('క్షుధ', 'ఆకలి, క్షుత్తు, బుభుక్ష')]:
    q(1, 2, f'‘{w}’ {PY}', a)
m(1, 'భాగవతంలో కృష్ణ లీలలు అబ్బురంగా తోస్తాయి. (గీత గీసిన పదం: అబ్బురం) ప్రకృతి పదం గుర్తించండి.', ['ఆశ్చర్యం', 'అక్కజం', 'అద్భుతం', 'అతిశయం'], 2, mk=2)
m(1, 'ఆకాశంలో పక్షి ఎగురుతోంది. (గీత గీసిన పదం: పక్షి) వికృతి పదం గుర్తించండి.', ['పక్కము', 'పక్కి', 'పగిది', 'పరుషము'], 1, mk=2)
